{"output": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]

    for r, c, v in points:
        if v == 1:
            # Two-cell horizontal 5 segment, followed by an up-right 1 tip.
            for dc in (1, 2):
                if c + dc < w:
                    out[r][c + dc] = 5
            if r > 0 and c + 2 < w:
                out[r - 1][c + 2] = 1
        elif v == 2:
            # Mirror the 2 four cells horizontally, with a 5 bridge.
            if c >= 4:
                out[r][c - 4] = 2
                for cc in range(c - 3, c):
                    out[r][cc] = 5
            else:
                out[r][c + 4] = 2
                for cc in range(c + 1, c + 4):
                    out[r][cc] = 5
        elif v == 3:
            # Two 5 cells below, followed by a 3 tip.
            for dr in (1, 2):
                if r + dr < h:
                    out[r + dr][c] = 5
            if r + 3 < h:
                out[r + 3][c] = 3
        elif v == 6:
            # Six-cell vertical ray to a copied 6, with 5 between.
            end_r = r - 6
            if end_r >= 0:
                out[end_r][c] = 6
                for rr in range(end_r + 1, r):
                    out[rr][c] = 5
            # Diagonal 4 ray starts two rows above and one column left,
            # then continues down-left through the source row.
            for k in range(3):
                rr, cc = r - 2 + k, c - 1 - k
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 4

    return out", "exit_code": 0, "error": null}

